<style>
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --primary-dark: #141414;
  --white: #FFFFFF;
  --light-gray: #F5F5F5;
  --mid-gray: #E5E5E5;
  --text-secondary: #6B6B6B;
  --accent: #6C5CE7;
  --accent-hover: #5A4BD1;
  --accent-light: #F0EEFF;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 100px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.1);
  --transition: 250ms cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--primary-dark);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== ANNOUNCEMENT BAR ===== */
.announcement-bar {
  background: var(--primary-dark);
  color: var(--white);
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.announcement-bar a {
  color: var(--accent);
  text-decoration: none;
  margin-left: 6px;
}

.announcement-bar a:hover { text-decoration: underline; }

/* ===== HEADER / NAV ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--mid-gray);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.logo {
  font-size: 20px;
  font-weight: 800;
  text-decoration: none;
  color: var(--primary-dark);
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg {
  width: 18px;
  height: 18px;
  fill: var(--white);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  text-decoration: none;
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  transition: color var(--transition);
}

.nav-links a:hover { color: var(--primary-dark); }

.nav-links .btn-login {
  color: var(--primary-dark);
  font-weight: 600;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.mobile-menu-btn span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--primary-dark);
  margin: 5px 0;
  transition: var(--transition);
}

/* ===== HERO ===== */
.hero {
  text-align: center;
  padding: 80px 24px 64px;
  background: linear-gradient(180deg, var(--white) 0%, var(--light-gray) 100%);
}

.hero h1 {
  font-size: clamp(36px, 5.5vw, 64px);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  max-width: 720px;
  margin: 0 auto 20px;
}

.hero p {
  font-size: clamp(16px, 2vw, 20px);
  color: var(--text-secondary);
  max-width: 560px;
  margin: 0 auto 36px;
  line-height: 1.5;
}

.hero-ctas {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--accent);
  color: var(--white);
  padding: 14px 28px;
  border-radius: var(--radius-pill);
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}

.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(108,92,231,0.35);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  color: var(--primary-dark);
  padding: 14px 28px;
  border-radius: var(--radius-pill);
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  border: 1.5px solid var(--mid-gray);
  cursor: pointer;
  transition: border-color var(--transition), transform var(--transition);
}

.btn-secondary:hover {
  border-color: var(--primary-dark);
  transform: translateY(-1px);
}

/* ===== TRUSTED BY ===== */
.trusted-by {
  padding: 48px 24px;
  text-align: center;
  background: var(--light-gray);
}

.trusted-by p {
  font-size: 13px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  margin-bottom: 28px;
}

.trusted-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;
  max-width: 900px;
  margin: 0 auto;
}

.trusted-logo {
  font-size: 18px;
  font-weight: 700;
  color: #BABABA;
  transition: color var(--transition);
  white-space: nowrap;
}

.trusted-logo:hover { color: var(--text-secondary); }

/* ===== STATS ===== */
.stats {
  padding: 80px 24px;
  text-align: center;
}

.stats-label {
  font-size: 14px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  margin-bottom: 40px;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  max-width: 800px;
  margin: 0 auto;
}

.stat-card {
  padding: 32px 16px;
}

.stat-number {
  font-size: clamp(40px, 6vw, 64px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--primary-dark);
  margin-bottom: 8px;
}

.stat-label {
  font-size: 16px;
  color: var(--text-secondary);
  font-weight: 500;
}

/* ===== FEATURES SEARCH ===== */
.features-search {
  padding: 80px 24px;
  background: var(--light-gray);
}

.section-header {
  text-align: center;
  max-width: 600px;
  margin: 0 auto 48px;
}

.section-header h2 {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-header p {
  font-size: 17px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.search-tabs {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  background: var(--white);
  border-radius: var(--radius-pill);
  padding: 4px;
  max-width: 600px;
  margin: 0 auto 24px;
  border: 1px solid var(--mid-gray);
}

.search-tab {
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  font-size: 14px;
  font-weight: 500;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.search-tab.active {
  background: var(--primary-dark);
  color: var(--white);
}

.search-tab:hover:not(.active) {
  color: var(--primary-dark);
  background: var(--light-gray);
}

.filter-pills {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 8px;
  margin-bottom: 32px;
  scrollbar-width: none;
  -ms-overflow-style: none;
  justify-content: center;
  flex-wrap: wrap;
}

.filter-pills::-webkit-scrollbar { display: none; }

.filter-pill {
  padding: 8px 18px;
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 500;
  border: 1.5px solid var(--mid-gray);
  background: var(--white);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}

.filter-pill.active {
  border-color: var(--accent);
  background: var(--accent-light);
  color: var(--accent);
}

.filter-pill:hover:not(.active) {
  border-color: var(--primary-dark);
  color: var(--primary-dark);
}

.screenshot-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 16px;
  max-width: 1000px;
  margin: 0 auto;
}

.screenshot-card {
  aspect-ratio: 9/16;
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--mid-gray);
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}

.screenshot-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.screenshot-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.screenshot-placeholder .app-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  margin-bottom: 12px;
}

.screenshot-placeholder .lines {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 12px;
}

.screenshot-placeholder .line {
  height: 6px;
  border-radius: 3px;
  background: var(--light-gray);
}

.screenshot-placeholder .line:nth-child(2) { width: 75%; }
.screenshot-placeholder .line:nth-child(3) { width: 50%; }

.screenshot-label {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 12px;
  background: linear-gradient(transparent, rgba(0,0,0,0.6));
  color: var(--white);
  font-size: 12px;
  font-weight: 500;
}

/* ===== FEATURES FLOWS ===== */
.features-flows {
  padding: 80px 24px;
}

.flows-toggle-wrap {
  display: flex;
  justify-content: center;
  margin-bottom: 40px;
}

.flows-toggle {
  display: flex;
  background: var(--light-gray);
  border-radius: var(--radius-pill);
  padding: 4px;
  gap: 4px;
}

.flows-toggle-btn {
  padding: 10px 24px;
  border-radius: var(--radius-pill);
  border: none;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  background: transparent;
  color: var(--text-secondary);
}

.flows-toggle-btn.active {
  background: var(--white);
  color: var(--primary-dark);
  box-shadow: var(--shadow-sm);
}

.flows-content {
  max-width: 900px;
  margin: 0 auto;
}

.flows-panel {
  display: none;
  animation: fadeSlide 300ms ease forwards;
}

.flows-panel.active { display: block; }

@keyframes fadeSlide {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.flows-visual {
  background: var(--light-gray);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
  border: 1px solid var(--mid-gray);
}

.flows-visual-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}

.flow-step {
  width: 120px;
  height: 210px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--mid-gray);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px;
  transition: transform var(--transition);
}

.flow-step:hover { transform: scale(1.05); }

.flow-step .step-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--accent-light);
}

.flow-step .step-lines {
  width: 80%;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.flow-step .step-line {
  height: 4px;
  border-radius: 2px;
  background: var(--light-gray);
}

.flow-step .step-line:nth-child(2) { width: 65%; }

.flow-arrow {
  color: var(--text-secondary);
  font-size: 20px;
  flex-shrink: 0;
}

.flows-description {
  margin-top: 24px;
  text-align: center;
  color: var(--text-secondary);
  font-size: 15px;
}

/* ===== FEATURES TOOLS ===== */
.features-tools {
  padding: 80px 24px;
  background: var(--light-gray);
}

.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 1000px;
  margin: 0 auto;
}

.tool-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--mid-gray);
  transition: transform var(--transition), box-shadow var(--transition);
}

.tool-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.tool-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 22px;
}

.tool-icon-figma { background: #F0EEFF; color: var(--accent); }
.tool-icon-save { background: #FFF3E0; color: #F57C00; }
.tool-icon-comment { background: #E8F5E9; color: #43A047; }

.tool-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 8px;
}

.tool-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ===== TESTIMONIALS ===== */
.testimonials {
  padding: 80px 24px;
  overflow: hidden;
}

.marquee-container {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 48px;
}

.marquee-row {
  display: flex;
  gap: 20px;
  width: max-content;
}

.marquee-row.scroll-left { animation: marqueeLeft 40s linear infinite; }
.marquee-row.scroll-right { animation: marqueeRight 40s linear infinite; }

@keyframes marqueeLeft {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marqueeRight {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.testimonial-card {
  flex-shrink: 0;
  width: 380px;
  background: var(--white);
  border: 1px solid var(--mid-gray);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: transform var(--transition);
}

.testimonial-card:hover { transform: scale(1.02); }

.testimonial-text {
  font-size: 14px;
  line-height: 1.65;
  color: var(--primary-dark);
  margin-bottom: 20px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  color: var(--white);
  flex-shrink: 0;
}

.testimonial-name {
  font-size: 14px;
  font-weight: 600;
}

.testimonial-company {
  font-size: 12px;
  color: var(--text-secondary);
}

/* ===== CTA ===== */
.cta-section {
  padding: 80px 24px;
  text-align: center;
  background: var(--primary-dark);
  color: var(--white);
  overflow: hidden;
}

.cta-section h2 {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}

.cta-section p {
  font-size: 17px;
  color: #A0A0A0;
  max-width: 520px;
  margin: 0 auto 36px;
  line-height: 1.5;
}

.cta-buttons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 60px;
}

.cta-section .btn-secondary {
  background: transparent;
  color: var(--white);
  border-color: rgba(255,255,255,0.25);
}

.cta-section .btn-secondary:hover {
  border-color: var(--white);
}

.brand-marquee-container {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 20px;
}

.brand-marquee-row {
  display: flex;
  gap: 24px;
  width: max-content;
}

.brand-marquee-row.scroll-left { animation: brandLeft 30s linear infinite; }
.brand-marquee-row.scroll-right { animation: brandRight 30s linear infinite; }

@keyframes brandLeft {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes brandRight {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.brand-icon {
  flex-shrink: 0;
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  color: rgba(255,255,255,0.5);
  transition: background var(--transition);
  border: 1px solid rgba(255,255,255,0.06);
}

.brand-icon:hover {
  background: rgba(255,255,255,0.14);
}

/* ===== FOOTER ===== */
.footer {
  padding: 64px 24px 32px;
  background: var(--primary-dark);
  color: rgba(255,255,255,0.6);
  border-top: 1px solid rgba(255,255,255,0.08);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  max-width: 1200px;
  margin: 0 auto 48px;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-tagline {
  font-size: 14px;
  line-height: 1.6;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  font-size: 14px;
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
}

.footer-bottom a {
  color: rgba(255,255,255,0.4);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-bottom a:hover { color: var(--white); }

.footer-legal {
  display: flex;
  gap: 20px;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .mobile-menu-btn { display: block; }

  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
