  // ===== Intersection Observer for fade-in =====
  const fadeEls = document.querySelectorAll('.fade-in');
  const fadeObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        fadeObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15 });
  fadeEls.forEach(function(el) { fadeObserver.observe(el); });

  // ===== Animated stat counters =====
  var statsAnimated = false;
  var statsSection = document.getElementById('statsSection');

  function formatNumber(n) {
    return n.toLocaleString('en-US');
  }

  function animateCounter(el, target, duration) {
    var start = 0;
    var startTime = null;
    function step(timestamp) {
      if (!startTime) startTime = timestamp;
      var progress = Math.min((timestamp - startTime) / duration, 1);
      var eased = 1 - Math.pow(1 - progress, 3);
      var current = Math.floor(eased * target);
      el.textContent = formatNumber(current);
      if (progress < 1) {
        requestAnimationFrame(step);
      } else {
        el.textContent = formatNumber(target);
      }
    }
    requestAnimationFrame(step);
  }

  var statsObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting && !statsAnimated) {
        statsAnimated = true;
        var counters = document.querySelectorAll('.stat-number[data-target]');
        counters.forEach(function(counter, i) {
          var target = parseInt(counter.getAttribute('data-target'), 10);
          setTimeout(function() {
            animateCounter(counter, target, 1800);
          }, i * 200);
        });
        statsObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });
  statsObserver.observe(statsSection);

  // ===== Search tabs =====
  var searchTabs = document.querySelectorAll('.search-tab');
  searchTabs.forEach(function(tab) {
    tab.addEventListener('click', function() {
      searchTabs.forEach(function(t) { t.classList.remove('active'); });
      tab.classList.add('active');
      renderGrid();
