        '</div>' +
        '</div>' +
        '<div class="screenshot-label">' + appNames[idx] + ' &middot; ' + filterText.replace(/-/g, ' ') + '</div>' +
        '</div>';
    }
    grid.innerHTML = html;
  }
  renderGrid();

  // ===== Flows toggle =====
