  });

  // ===== Testimonials marquee =====
  var testimonials = [
    { name: 'Sebastian Speier', company: 'Shop', text: 'ScreenVault is a great resource and it always comes in handy to see what the best practices or standards are for mobile patterns in our current landscape.', color: '#6C5CE7' },
    { name: 'Meng To', company: 'DesignCode', text: "ScreenVault is a game-changer for designers looking to step up their understanding of UX and UI design patterns. It\u2019s so massive, meticulously organized, has deep user flows and even a Figma plugin! It\u2019s indispensable in the modern designer\u2019s toolbox.", color: '#00B894' },
    { name: 'Marco Cornacchia', company: 'Figma', text: "ScreenVault is one of my favorite resources for product design and UI inspo. I love having access to a ton of \u2018real world examples\u2019 to see how different apps and companies handle specific UI patterns and flows.", color: '#E17055' },
    { name: 'Daryl Ginn', company: 'Endless', text: 'ScreenVault has quickly become our favourite inspiration resource for designing mobile apps at endless.design, their advanced filtering is unmatched in the inspiration space.', color: '#0984E3' },
    { name: 'Rachel How', company: '', text: "ScreenVault is my go-to reference for app & web design. Apart from saving countless hours, it gives me insights on the design patterns, copywriting, and user flows of world-class products. A must-have for creative inspiration and efficiency!", color: '#FDCB6E' },
    { name: 'Haerin Song', company: 'Visa', text: 'By using the ScreenVault app, I save both my research time and space in my photo galleries filled with random screenshots. I love how easy it is to search for different patterns and copy and paste flows into Figma. It is a wonderful design tool you cannot live without!', color: '#A29BFE' }
