  function createBrandIcon(name) {
    var abbr = name.length <= 4 ? name : name.substring(0, 3);
    return '<div class="brand-icon" title="' + name + '">' + abbr + '</div>';
  }

  var br1 = document.getElementById('brandRow1');
  var br2 = document.getElementById('brandRow2');
